import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.2cFhd8Ux.js";const p=JSON.parse('{"title":"Landscape Report: Teaching Agentic Software Engineering to Seniors and Graduate Students","description":"","frontmatter":{"source":"research/landscape-report-2026-11.md"},"headers":[],"relativePath":"research/landscape-report-2026-11.md","filePath":"research/landscape-report-2026-11.md"}'),s={name:"research/landscape-report-2026-11.md"};function n(i,e,l,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="landscape-report-teaching-agentic-software-engineering-to-seniors-and-graduate-students" tabindex="-1">Landscape Report: Teaching Agentic Software Engineering to Seniors and Graduate Students <a class="header-anchor" href="#landscape-report-teaching-agentic-software-engineering-to-seniors-and-graduate-students" aria-label="Permalink to &quot;Landscape Report: Teaching Agentic Software Engineering to Seniors and Graduate Students&quot;">​</a></h1><blockquote><p><strong>November 2026.</strong> A synthesis of the three research notes behind Engineering Software with AI: <a href="./notes/courses-upper-division.html">comparable courses</a>, <a href="./notes/tools-senior.html">the $0 tool landscape</a> (checked 2026-11-02) and <a href="./notes/evidence-senior.html">the evidence base</a>. Every claim links to its source; where a source is a preprint, a vendor or a search summary, the text says so. This is a dated record: current tool facts live in <a href="./../TOOLS.html">Tool Handout</a>, and the decisions this report led to are in <a href="./design-rationale.html">Why the Course Looks Like This</a>.</p></blockquote><p><strong>On this page:</strong> <a href="#summary">Summary</a> · <a href="#1-comparable-courses">1. Comparable courses</a> · <a href="#2-team-projects-on-real-codebases">2. Team projects on real codebases</a> · <a href="#3-graduate-differentiation">3. Graduate differentiation</a> · <a href="#4-the-evidence-base">4. The evidence base</a> · <a href="#5-the-0-tool-landscape">5. The $0 tool landscape</a> · <a href="#6-design-implications">6. Design implications</a> · <a href="#7-gaps">7. Gaps</a></p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><ol><li><strong>Upper-division courses on agentic software engineering now exist, and they agree on more than they differ.</strong> UT Austin&#39;s CS 378 frames the work as deciding &quot;what you specify, what you delegate, and what you verify&quot;, teaches prompt injection and sandboxing in week 3, opens each homework due date with a 7-minute AI-free quiz, and ends with a live defense graded on evidence rather than feature count (<a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">CS 378</a>). Michigan&#39;s EECS 498 runs at $0 on local models and moved its projects into a real 20,000-line agent codebase (<a href="https://github.com/eecs498-aase/materials/blob/HEAD/labs/Lab03/slides.md" target="_blank" rel="noreferrer">Lab03</a>). CMU 17-313 has teams work in a class fork of an open-source agent, graded from deadline snapshots (<a href="https://cmu-313.github.io/assignments/P1/" target="_blank" rel="noreferrer">17-313</a>).</li><li><strong>Building an agent from scratch works as one week, not a project.</strong> Michigan replaced its own &quot;build the agent&quot; lab and dropped a stand-alone eval suite after student feedback (<a href="https://eecs498-aase.github.io/syllabus.html" target="_blank" rel="noreferrer">AASE syllabus</a>). The pattern that remains is a short build, then extending a real harness.</li><li><strong>Grading upstream merges is a mistake, and 2026 makes it worse.</strong> Before agents, 44% of student PRs to real projects were accepted, and the authors advise against grading acceptance (<a href="https://web.eecs.umich.edu/~weimerw/p/weimer-fse2023.pdf" target="_blank" rel="noreferrer">Fang et al.</a>). Maintainers have since banned, restricted or throttled AI-assisted contributions (<a href="https://github.com/qemu/qemu/blob/master/docs/devel/code-provenance.rst" target="_blank" rel="noreferrer">QEMU</a>; <a href="https://github.com/ghostty-org/ghostty/blob/main/AI_POLICY.md" target="_blank" rel="noreferrer">Ghostty</a>; <a href="https://hacktoberfest.com/llms.txt" target="_blank" rel="noreferrer">Hacktoberfest</a>).</li><li><strong>The evidence base is now large enough to teach from, and it is sobering.</strong> Better-designed studies find smaller, less certain speed effects; output rises while quality signals worsen (<a href="https://arxiv.org/abs/2511.04427" target="_blank" rel="noreferrer">He et al.</a>); every major SWE benchmark overstates capability (<a href="https://metr.org/notes/2026-03-10-many-swe-bench-passing-prs-would-not-be-merged-into-main/" target="_blank" rel="noreferrer">METR</a>); LLM-written tests encode what code does, not what it should do (<a href="https://arxiv.org/abs/2410.21136" target="_blank" rel="noreferrer">Konstantinou et al.</a>); and agents that read untrusted text are exploitable by design (<a href="https://arxiv.org/abs/2509.22040" target="_blank" rel="noreferrer">Liu et al.</a>).</li><li><strong>On a $0 budget the scarce resource is model capacity, not tools.</strong> Every harness worth teaching is free; the inference attached to free plans is small, about $2 a month on Copilot Student by third-party reports, against about $1.50 for one default-effort Copilot code review (<a href="./notes/tools-senior.html">tool notes</a>). A $0 course must spread work across several free pools and a lab-served local model.</li><li><strong>Graduate differentiation at UIdaho is a one-line catalog promise</strong> (&quot;Additional projects/assignments required for graduate credit&quot;), and peer courses put graduate extras at about 15–25% of the grade, through presentations, critiques and a research project (<a href="https://catalog.uidaho.edu/courses/cs/" target="_blank" rel="noreferrer">UIdaho catalog</a>; <a href="https://danny.cs.colorado.edu/courses/csci7000-005_Sp26/index.html" target="_blank" rel="noreferrer">CU Boulder</a>).</li></ol><p><strong>What this means for the course:</strong> the triad; a one-week agent build followed by a real harness; security before teams give agents broad access; verification measured by mutation score; a three-tier project graded on process; AI-free due-date quizzes and oral exams; a graduate track of presentations and a $0 replication study; and a tool stack that spreads load across free pools plus a lab machine (<a href="#6-design-implications">section 6</a>).</p><hr><h2 id="1-comparable-courses" tabindex="-1">1. Comparable courses <a class="header-anchor" href="#1-comparable-courses" aria-label="Permalink to &quot;1. Comparable courses&quot;">​</a></h2><h3 id="who-teaches-what" tabindex="-1">Who teaches what <a class="header-anchor" href="#who-teaches-what" aria-label="Permalink to &quot;Who teaches what&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Course</th><th>Level and prerequisite</th><th>Weights</th><th>Tools and cost</th><th>Project model</th></tr></thead><tbody><tr><td>UT Austin CS 378 Agentic Software Engineering (Fall 2026)</td><td>Upper division; systems prerequisite</td><td>Quizzes 12, homework 58, final project 30</td><td>Codex and Claude Code through university accounts, $0</td><td>Four homeworks (solo or pairs, new partner each time), a peer PR round, a final with live defense</td></tr><tr><td>Michigan EECS 498 AASE (Fall 2026)</td><td>Upper division</td><td>Admin 10, Apply 18, Analyze 22.5, Create 49.5</td><td>Ollama and Aider, then Codex on course credit, $0</td><td>Individual; projects inside Aider&#39;s codebase</td></tr><tr><td>UMD CMSC 389A (Fall 2026)</td><td>Sophomore and up</td><td>Projects 40, final project 15, quizzes 5, two midterms 20, final exam 10, participation 10</td><td>Claude Pro required, $20/month</td><td>Pair and group projects</td></tr><tr><td>UVA CS 4501 (Fall 2026)</td><td>4000 level</td><td>Attendance 20, quizzes 20, assignments 20, project 40</td><td>Not stated</td><td>Small-team project, weeks 9–15</td></tr><tr><td>ANU COMP4020/8020 (2026)</td><td>Undergraduate and postgraduate</td><td>Crits 20, two assignments 20 each, final 40</td><td>Claude Code</td><td>Weekly studio crits; full-stack final</td></tr><tr><td>Cornell CS 6158 (Fall 2026)</td><td>PhD/MS seminar</td><td>Participation 20, presentations 20, assignments 10, project 50</td><td>Not stated</td><td>Research project in pairs</td></tr><tr><td>CU Boulder CSCI 7000-05 (Spring 2026)</td><td>Graduate seminar</td><td>Participation 10, critiques 20, presentation 20, project 50</td><td>Not stated</td><td>Teams of 3–4</td></tr></tbody></table><p>Sources: <a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">CS 378</a>; <a href="https://eecs498-aase.github.io/syllabus.html" target="_blank" rel="noreferrer">AASE</a>; <a href="https://www.cs.umd.edu/class/fall2026/cmsc389A/Syllabus.html" target="_blank" rel="noreferrer">CMSC 389A</a>; <a href="https://www.cs.virginia.edu/~se4ja/files/seLLMs2026.html" target="_blank" rel="noreferrer">UVA</a>; <a href="https://comp.anu.edu.au/courses/comp4020-agentic-coding-studio/" target="_blank" rel="noreferrer">ANU</a>; <a href="https://www.cs.cornell.edu/courses/cs6158/2026fa/" target="_blank" rel="noreferrer">Cornell</a>; <a href="https://danny.cs.colorado.edu/courses/csci7000-005_Sp26/syllabus.html" target="_blank" rel="noreferrer">CU Boulder</a>.</p><h3 id="what-they-teach-and-in-what-order" tabindex="-1">What they teach, and in what order <a class="header-anchor" href="#what-they-teach-and-in-what-order" aria-label="Permalink to &quot;What they teach, and in what order&quot;">​</a></h3><p>The topics converge: the agent loop and harness architecture, context engineering, specifications, security of agents, testing and verification, review, parallel agents, and evaluation. The order differs in instructive ways.</p><ul><li><strong>UT Austin</strong> puts &quot;prompt injection and the lethal trifecta; permissions and sandboxing&quot; in <strong>week 3</strong>, then &quot;Parallelize a task once you can name its merge point&quot; in week 4, secrets with agents in week 9, and &quot;Rewards and benchmarks: A test suite rewards and grades until its answers leak&quot; in week 13 (<a href="https://www.cs.utexas.edu/~witchel/378AC/schedule.html" target="_blank" rel="noreferrer">schedule</a>). Its homeworks arrive &quot;in beats&quot;: &quot;you build v1 against a spec, then the spec changes under you&quot; (<a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">CS 378</a>).</li><li><strong>Michigan</strong> goes from the landscape and how LLMs code to spec-driven development, agentic CLIs, orchestration, &quot;the raw call&quot;, stop conditions and approval, skills and the <strong>Elephant-Goldfish Model</strong>, and guardrails, then subagents, compaction and memory (<a href="https://eecs498-aase.github.io/syllabus.html" target="_blank" rel="noreferrer">syllabus</a>). Its rebuilt project has students add a skills loader, a tool loop, a shell tool behind approval rules and an MCP client to Aider, graded 50% design and 50% behavior, with a design document committed before implementation.</li><li><strong>ANU</strong> marks its assignments &quot;on the legibility of your process&quot; and asks for &quot;a definition of good that you make and defend&quot; (<a href="https://comp.anu.edu.au/courses/comp4020-agentic-coding-studio/" target="_blank" rel="noreferrer">ANU</a>).</li><li><strong>Stanford CS146S</strong> has students run an agent-readiness assessment on three open-source repositories and warns: &quot;Three repos is a small sample. Scope your claims to what it supports&quot; (<a href="https://github.com/mihail911/modern-software-dev-assignments/blob/df18839a81/week5/assignment.md" target="_blank" rel="noreferrer">W5 spec</a>).</li><li><strong>Cornell and CU Boulder</strong> are paper seminars: evaluation (SWE-bench variants, reward hacking), security of agents, verification and specification inference at Cornell (<a href="https://www.cs.cornell.edu/courses/cs6158/2026fa/schedule.html" target="_blank" rel="noreferrer">schedule</a>); ReAct, Reflexion, SWE-agent and agent-configuration studies at CU Boulder (<a href="https://danny.cs.colorado.edu/courses/csci7000-005_Sp26/index.html" target="_blank" rel="noreferrer">CSCI 7000-05</a>).</li></ul><h3 id="how-they-grade" tabindex="-1">How they grade <a class="header-anchor" href="#how-they-grade" aria-label="Permalink to &quot;How they grade&quot;">​</a></h3><p>Three practices recur in the courses that publish detail.</p><ol><li><strong>Short AI-free checks tied to the work.</strong> UT Austin opens each homework due date with &quot;a 7-minute individual quiz on that homework&quot;, all quizzes AI-free with &quot;only a single browser tab open&quot; (<a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">CS 378</a>). UMD and UVA use quizzes and exams for 25–40% of the grade (<a href="https://www.cs.umd.edu/class/fall2026/cmsc389A/Syllabus.html" target="_blank" rel="noreferrer">389A</a>; <a href="https://www.cs.virginia.edu/~se4ja/files/seLLMs2026.html" target="_blank" rel="noreferrer">UVA</a>).</li><li><strong>Process evidence over output.</strong> UT Austin&#39;s final is graded on &quot;demonstrated behavior, reproducible checks, controlled engineering decisions, or honest limitations&quot;, not &quot;feature count, repository size, token spend, prompt volume, and visual polish&quot;, and &quot;Commit history is part of the evaluation&quot; (<a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">CS 378</a>).</li><li><strong>A live defense or explanation.</strong> UT Austin&#39;s final includes a live defense; Michigan grades design as half of each project (<a href="https://eecs498-aase.github.io/syllabus.html" target="_blank" rel="noreferrer">AASE</a>).</li></ol><p><strong>Cost.</strong> UT Austin provides agents through university accounts and still concedes that &quot;students who add more generous personal subscriptions have an advantage&quot;; it also refuses &quot;I ran out of credit&quot; as an excuse (<a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">CS 378</a>). UMD requires a $20/month subscription (<a href="https://www.cs.umd.edu/class/fall2026/cmsc389A/Syllabus.html" target="_blank" rel="noreferrer">389A</a>). Michigan is $0 by design: &quot;A small model punishes sloppy engineering visibly; that is the point&quot; (<a href="https://eecs498-aase.github.io/syllabus.html" target="_blank" rel="noreferrer">AASE</a>, via the <a href="./notes/tools-senior.html">tool notes</a>).</p><h3 id="what-changed-mid-course" tabindex="-1">What changed mid-course <a class="header-anchor" href="#what-changed-mid-course" aria-label="Permalink to &quot;What changed mid-course&quot;">​</a></h3><p>Michigan&#39;s pivot is the most useful data point. Its Lab03 &quot;replaces the &#39;Build the agent&#39; lab&quot;; of 49 students asked what they&#39;d want to learn with Codex, about 23 wanted to use the tools well, 8 design and specs, 7 orchestration and skills, and &quot;almost nobody asked what to build with it&quot; (<a href="https://github.com/eecs498-aase/materials/blob/HEAD/labs/Lab03/slides.md" target="_blank" rel="noreferrer">Lab03</a>). The former eval suite and teardown report &quot;are no longer required&quot; (<a href="https://eecs498-aase.github.io/syllabus.html" target="_blank" rel="noreferrer">syllabus</a>). The required order is now &quot;Learn, then design, then build&quot;, because &quot;A one-shot prompt gives you the model&#39;s design, not yours&quot; (<a href="https://github.com/eecs498-aase/materials/blob/HEAD/labs/Lab03/slides.md" target="_blank" rel="noreferrer">Lab03</a>). Reference agents remain small: mini-swe-agent is about 100 lines of Python (<a href="https://github.com/SWE-agent/mini-swe-agent" target="_blank" rel="noreferrer">repo</a>), Thorsten Ball&#39;s is under 400 lines of Go (<a href="https://ampcode.com/how-to-build-an-agent" target="_blank" rel="noreferrer">Amp</a>).</p><p>No course has published outcome data for mutation-testing, prompt-injection or parallel-agent labs (<a href="./notes/courses-upper-division.html#q5-labs-that-worked-or-failed">courses notes, Q5</a>).</p><h2 id="2-team-projects-on-real-codebases" tabindex="-1">2. Team projects on real codebases <a class="header-anchor" href="#2-team-projects-on-real-codebases" aria-label="Permalink to &quot;2. Team projects on real codebases&quot;">​</a></h2><p><strong>The class-fork model.</strong> CMU 17-313 builds &quot;upon opencode, the open source AI coding agent&quot; in a class-specific fork: &quot;We will ONLY be working with the course specific repo in this class.&quot; Each student owns a backlog issue with a PR to the team repository that has &quot;at least some teammate review&quot;; &quot;The PR does not need to be merged yet&quot;; grading uses &quot;a snapshot of your repository (including open branches and PRs)&quot; at the deadline (<a href="https://cmu-313.github.io/assignments/P1/" target="_blank" rel="noreferrer">P1</a>; <a href="https://cmu-313.github.io/assignments/P2/2_firstsprint/" target="_blank" rel="noreferrer">P2B</a>). Onboarding starts with a measurable refactor that removes a code smell (<a href="https://cmu-313.github.io/assignments/P1/2_refactoring/" target="_blank" rel="noreferrer">P1B</a>).</p><p><strong>The peer PR round.</strong> At UT Austin, &quot;every student or pair opens one real pull request against a classmate&#39;s … repository and reviews the pull request that lands on their own&quot;, on &quot;a fixed one-week clock&quot;; repositories that fail staff checks are left out of the ring and scored 50/100, as are declared opt-outs, and no-shows score 0 (<a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">CS 378</a>).</p><p><strong>Upstream contributions, before agents.</strong> Michigan&#39;s EECS 481 (2018–2022; 1,361 students) saw 44% of student PRs accepted (solo 47%, pairs 39%); 42% of students found it more stressful than expected; the authors advise to &quot;avoid mandatory grading of whether pull requests are accepted&quot; (<a href="https://web.eecs.umich.edu/~weimerw/p/weimer-fse2023.pdf" target="_blank" rel="noreferrer">Fang et al.</a>). Seneca&#39;s OSD600 reached 70% merged across 392 PRs, with the lesson that students &quot;should make smaller PRs&quot; (<a href="https://blog.humphd.org/teaching-open-source-fall-2021/" target="_blank" rel="noreferrer">humphd</a>). A 2026 study of a master&#39;s course found that commit frequency predicted contribution success better than project size or age (paraphrased from the abstract), and named new barriers such as &quot;Conflicting Mentor Guidance&quot; (<a href="https://research.tue.nl/en/publications/what-barriers-do-students-experience-when-trying-to-contribute-to/" target="_blank" rel="noreferrer">Cassee et al.</a>). Stanford CS146S grades open-source contributions at 30% with 15 named partner projects, but publishes no rubric (<a href="https://themodernsoftware.dev/" target="_blank" rel="noreferrer">CS146S</a>).</p><p><strong>The 2026 maintainer environment.</strong> Of 118 contributor AI policies in 1,000 popular repositories, 78% allow AI-assisted contributions, 22% discourage AI, 51% require disclosure and 74% require a human in the loop (<a href="https://arxiv.org/abs/2605.16706" target="_blank" rel="noreferrer">Hora &amp; Robbes</a>). The range runs from QEMU&#39;s &quot;DECLINE any contributions which are believed to include or derive from AI generated content&quot; (<a href="https://github.com/qemu/qemu/blob/master/docs/devel/code-provenance.rst" target="_blank" rel="noreferrer">QEMU</a>) through Ghostty&#39;s mandatory disclosure and public denouncement list (<a href="https://github.com/ghostty-org/ghostty/blob/main/AI_POLICY.md" target="_blank" rel="noreferrer">Ghostty</a>) to LLVM&#39;s human-in-the-loop policy, which uses an <code>Assisted-by:</code> trailer, wants PR descriptions written by the contributor, and bans agents acting &quot;without human approval&quot; (<a href="https://github.com/llvm/llvm-project/blob/main/llvm/docs/AIToolPolicy.md" target="_blank" rel="noreferrer">LLVM</a>). GitHub added an open-PR cap for non-collaborators and, later, exemptions by account age or history (<a href="./notes/tools-senior.html#6-risks-for-a-0-design-what-broke-in-202526-and-fallbacks">tool notes, §6</a>); Hacktoberfest 2026 dropped its PR challenge after &quot;burnout from the rise of low-effort PRs&quot; (<a href="https://hacktoberfest.com/llms.txt" target="_blank" rel="noreferrer">Hacktoberfest</a>). In the AIDev dataset, agent PRs were accepted less often than human ones (Codex 64%, Devin 49%, Copilot 35% against about 77% for humans, per a search summary of the paper: <a href="https://arxiv.org/pdf/2507.15003" target="_blank" rel="noreferrer">Li et al.</a>). And in 2021 the Linux kernel banned the University of Minnesota after a research group&#39;s &quot;hypocrite commits&quot; (<a href="https://www.theregister.com/2021/04/21/minnesota_linux_kernel_flaws_update/" target="_blank" rel="noreferrer">The Register</a>): one group&#39;s behavior can block an institution.</p><p><strong>The resulting model</strong> is three tiers: graded core work in a class fork; a peer PR round across team forks; optional upstream PRs to a pre-vetted list with maintainer contact, graded on process with merges as a bonus (<a href="./notes/courses-upper-division.html#q2-team-projects-on-existing-open-source-codebases">courses notes, Q2</a>). Expect 40–70% merge rates from the pre-AI data, and lower in 2026 (an inference).</p><h2 id="3-graduate-differentiation" tabindex="-1">3. Graduate differentiation <a class="header-anchor" href="#3-graduate-differentiation" aria-label="Permalink to &quot;3. Graduate differentiation&quot;">​</a></h2><p>UIdaho&#39;s CS catalog states the graduate difference for joint-listed courses in one sentence, most often &quot;Additional projects/assignments required for graduate credit&quot;; others name an &quot;extra term paper&quot; or &quot;additional class presentation and/or paper&quot; (<a href="https://catalog.uidaho.edu/courses/cs/" target="_blank" rel="noreferrer">catalog</a>). Regulation B-11 says a student &quot;may only earn credit at the level the student initially completes the course&quot; (<a href="https://catalog.uidaho.edu/general-requirements-academic-procedures/b-registration/" target="_blank" rel="noreferrer">B-Registration</a>).</p><p>Peer courses that publish a difference use research work. ANU&#39;s COMP8020 adds a 1,000-word critical research note worth about 4% of the course (<a href="https://programsandcourses.anu.edu.au/2026/course/COMP8020/Second%20Semester/9057" target="_blank" rel="noreferrer">ANU P&amp;C</a>); CMU&#39;s 17-745 &quot;replaces two homework assignments with a mandatory research project&quot; (<a href="https://mlip-cmu.github.io/f2025" target="_blank" rel="noreferrer">MLiP</a>). Several dual-listed courses publish no difference at all (<a href="./notes/courses-upper-division.html#q3-undergraduategraduate-differentiation-in-joint-listed-courses">courses notes, Q3</a>). Graduate seminars supply the rubrics: CU Boulder&#39;s presentation rubric (content 30, value added 30, materials 20, moderating discussion 20) and its &quot;Tool Experience Report&quot; alternative to a critique (<a href="https://danny.cs.colorado.edu/courses/csci7000-005_Sp26/paperPresentation.html" target="_blank" rel="noreferrer">presentation</a>; <a href="https://danny.cs.colorado.edu/courses/csci7000-005_Sp26/paperCritiques.html" target="_blank" rel="noreferrer">critiques</a>), and Cornell&#39;s presenter–discussant roles with classmates&#39; questions (<a href="https://www.cs.cornell.edu/courses/cs6158/2026fa/" target="_blank" rel="noreferrer">CS 6158</a>).</p><p>Graduate extras of about 15–25% of the 5000-level grade fit both precedent and peers; studies should use public data or students&#39; own artifacts, never intervene on maintainers or classmates without IRB review (<a href="./notes/courses-upper-division.html#q3-undergraduategraduate-differentiation-in-joint-listed-courses">courses notes, Q3</a>).</p><h2 id="4-the-evidence-base" tabindex="-1">4. The evidence base <a class="header-anchor" href="#4-the-evidence-base" aria-label="Permalink to &quot;4. The evidence base&quot;">​</a></h2><p>The annotated bibliography is in <a href="./notes/evidence-senior.html">Evidence Base and Reading List: &quot;Engineering Software with AI&quot; (CS 4xxx/5xxx)</a>; this section gives the teaching points. Nineteen items suit graduate presentations, and five can be replicated at $0 in about four weeks (<a href="./../resources/reading-list.html">reading list</a>).</p><h3 id="productivity-and-quality" tabindex="-1">Productivity and quality <a class="header-anchor" href="#productivity-and-quality" aria-label="Permalink to &quot;Productivity and quality&quot;">​</a></h3><p>Randomized Copilot rollouts with 4,867 developers produced 26.08% more completed tasks (SE 10.3%), with juniors gaining far more than seniors, and code quality unmeasured (<a href="https://pubsonline.informs.org/doi/fpi/10.1287/mnsc.2025.00535" target="_blank" rel="noreferrer">Cui et al.</a>). Google&#39;s enterprise RCT estimated about 21% less time, with a wide interval (<a href="https://arxiv.org/abs/2410.12944" target="_blank" rel="noreferrer">Paradis et al.</a>). A preregistered study found AI cut completion time 30.7%, but other developers evolving that code later showed no difference in time or quality (<a href="https://arxiv.org/abs/2507.00788" target="_blank" rel="noreferrer">Borg et al.</a>). Observational repository studies show the quality side: after Cursor adoption, lines added rose 281% in month 1 and faded within about two months while static-analysis warnings (+29.7%) and complexity stayed high (<a href="https://arxiv.org/abs/2511.04427" target="_blank" rel="noreferrer">He et al.</a>); agent-first repositories without a committed AI configuration saw complexity rise 53% against 27% with one (<a href="https://arxiv.org/abs/2608.25241" target="_blank" rel="noreferrer">Denisov-Blanch et al.</a>). Of 567 Claude Code PRs in 157 projects, 83.8% were merged, but 45.1% of those needed further changes (<a href="https://arxiv.org/abs/2509.14745" target="_blank" rel="noreferrer">Watanabe et al.</a>); and rejection is a noisy label, with only 35.7% of rejections clear agent failures (<a href="https://arxiv.org/abs/2605.22534" target="_blank" rel="noreferrer">Peralta et al.</a>). <strong>Teaching point:</strong> output proxies rise; quality signals tend to worsen; nobody measures delivered value.</p><h3 id="benchmarks" tabindex="-1">Benchmarks <a class="header-anchor" href="#benchmarks" aria-label="Permalink to &quot;Benchmarks&quot;">​</a></h3><p>Every major SWE benchmark has been shown to overstate capability. SWE-bench Verified&#39;s co-creator stopped reporting it (<a href="https://openai.com/index/why-we-no-longer-evaluate-swe-bench-verified/" target="_blank" rel="noreferrer">OpenAI</a>). Filtering solution leakage and weak tests cut one agent&#39;s resolve rate from 12.47% to 3.97% (<a href="https://arxiv.org/abs/2410.06992" target="_blank" rel="noreferrer">SWE-Bench+</a>); 29.6% of plausible patches behave differently from the ground truth (<a href="https://arxiv.org/abs/2503.15223" target="_blank" rel="noreferrer">Wang, Pradel &amp; Liu</a>); models name the buggy file from the issue alone 76% of the time on SWE-bench against 53% elsewhere (<a href="https://arxiv.org/abs/2506.12286" target="_blank" rel="noreferrer">Liang et al.</a>); and maintainers&#39; merge rate for test-passing agent PRs ran 24.2 points below the automated grader (<a href="https://metr.org/notes/2026-03-10-many-swe-bench-passing-prs-would-not-be-merged-into-main/" target="_blank" rel="noreferrer">METR</a>). The Agentic Benchmark Checklist shows reward flaws can distort scores by up to 100% in relative terms (<a href="https://arxiv.org/abs/2507.02825" target="_blank" rel="noreferrer">Zhu et al.</a>). Meanwhile METR&#39;s time horizon has doubled roughly every 7 months since 2019 (<a href="https://arxiv.org/abs/2503.14499" target="_blank" rel="noreferrer">Kwa et al.</a>). <strong>Teaching point:</strong> a score is model plus scaffold plus test adequacy plus contamination; ask which harness, what &quot;pass&quot; means, whether tasks predate the cutoff, whether it is pass^k with an interval, and whether it survives the checklist.</p><h3 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h3><p>LLM-written tests reach easy coverage and miss boundaries: on 3,909 real functions, 45.1% statement coverage and a 40.2% mutation score (<a href="https://arxiv.org/abs/2508.00408" target="_blank" rel="noreferrer">Huang et al.</a>); boundary inputs such as null (34.8%) and empty (38.8%) are rarely tested (<a href="https://arxiv.org/abs/2610.32548" target="_blank" rel="noreferrer">Shi et al.</a>); and LLM oracles &quot;capture actual rather than expected behaviour&quot; (<a href="https://arxiv.org/abs/2410.21136" target="_blank" rel="noreferrer">Konstantinou, Degiovanni &amp; Papadakis</a>). Mutation is the better gate, and LLMs are good at it: Meta&#39;s mutation-guided generator had 73% of its tests accepted, with an equivalent-mutant detector at 0.95 precision (<a href="https://arxiv.org/abs/2501.12862" target="_blank" rel="noreferrer">Foster et al.</a>), and LLM mutants detected 87.98% of real faults against 41.64% for rule-based ones (<a href="https://arxiv.org/abs/2406.09843" target="_blank" rel="noreferrer">Wang et al.</a>). But a 2026 replication found coverage and mutation scores unreliable as effectiveness measures when the code may already be buggy, which is the typical case for AI-written code (<a href="https://arxiv.org/abs/2607.22880" target="_blank" rel="noreferrer">Zhao, Zhou &amp; Cohen</a>). Agentic property-based testing found valid bugs across 100 Python packages, with patches merged (<a href="https://arxiv.org/abs/2510.09907" target="_blank" rel="noreferrer">Maaz et al.</a>), and formal verification is becoming reachable: verified code for 82% of Dafny specifications (<a href="https://arxiv.org/abs/2509.22908" target="_blank" rel="noreferrer">Bursuc et al.</a>), with the bottleneck moving to writing specifications (<a href="https://martin.kleppmann.com/2025/12/08/ai-formal-verification.html" target="_blank" rel="noreferrer">Kleppmann</a>).</p><h3 id="review-ci-and-static-analysis" tabindex="-1">Review, CI and static analysis <a class="header-anchor" href="#review-ci-and-static-analysis" aria-label="Permalink to &quot;Review, CI and static analysis&quot;">​</a></h3><p>Deployed AI reviewers lead to changes less often than humans, and their effect on cycle time goes either way: at Beko, 73.8% of AI comments were resolved but closure time rose 42% (<a href="https://arxiv.org/abs/2412.18531" target="_blank" rel="noreferrer">Cihan et al.</a>); at Atlassian, 38.7% of AI comments led to changes against 44.45% of human ones, and cycle time fell 30.8% (<a href="https://arxiv.org/abs/2601.01129v2" target="_blank" rel="noreferrer">Tantithamthavorn et al.</a>). PRs reviewed only by agents merged 45.2% of the time against 68.4% with humans, and 12 of 13 agents had signal ratios below 60% (<a href="https://arxiv.org/abs/2604.03196" target="_blank" rel="noreferrer">Chowdhury et al.</a>). Concise, snippet-bearing or manually triggered comments lead to changes more often (<a href="https://arxiv.org/abs/2508.18771" target="_blank" rel="noreferrer">Sun et al.</a>). An LLM feeding a sound analyzer can double what it finds: CodeQL found 27 of 120 CVEs, IRIS with GPT-4 found 55 (<a href="https://arxiv.org/abs/2405.17238" target="_blank" rel="noreferrer">Li, Dutta &amp; Naik</a>). <strong>Teaching point:</strong> signal-to-noise is the design problem.</p><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><p>Working code is often insecure: about half of BaxBench&#39;s correct backends were exploitable (<a href="https://arxiv.org/abs/2502.11844" target="_blank" rel="noreferrer">Vero et al.</a>). Agents that read untrusted text are exploitable by design: planted payloads made agentic editors run malicious commands up to 84% of the time (<a href="https://arxiv.org/abs/2509.22040" target="_blank" rel="noreferrer">Liu et al.</a>); MCP tool descriptions can carry hidden instructions (<a href="https://invariantlabs.ai/blog/mcp-security-notification" target="_blank" rel="noreferrer">Invariant Labs</a>); one MCP server can supply all three legs of the lethal trifecta (<a href="https://simonwillison.net/2025/Jul/6/supabase-mcp-lethal-trifecta/" target="_blank" rel="noreferrer">Willison</a>); and an agent could be made to switch itself into auto-approve mode (<a href="https://cybersecuritynews.com/github-copilot-rce-vulnerability/" target="_blank" rel="noreferrer">CVE-2025-53773</a>). The defenses that hold are architectural: CaMeL&#39;s capability policies keep 77% of tasks solvable with provable security (<a href="https://arxiv.org/abs/2503.18813" target="_blank" rel="noreferrer">Debenedetti et al.</a>), design patterns trade utility for provable resistance (<a href="https://arxiv.org/abs/2506.08837" target="_blank" rel="noreferrer">Beurer-Kellner et al.</a>), and both filesystem and network isolation are needed (<a href="https://www.anthropic.com/engineering/claude-code-sandboxing" target="_blank" rel="noreferrer">Anthropic</a>). The supply chain is part of the same threat: Shai-Hulud compromised 500+ npm packages (<a href="https://www.cisa.gov/news-events/alerts/2025/09/23/widespread-supply-chain-compromise-impacting-npm-ecosystem" target="_blank" rel="noreferrer">CISA</a>), and OWASP&#39;s 2026 list puts Prompt Injection first and Excessive Agency third (<a href="https://genai.owasp.org/resource/owasp-genai-llm-top-10-2026/" target="_blank" rel="noreferrer">OWASP</a>).</p><h3 id="evals" tabindex="-1">Evals <a class="header-anchor" href="#evals" aria-label="Permalink to &quot;Evals&quot;">​</a></h3><p>An eval is an experiment. Criteria drift once you look at outputs (<a href="https://arxiv.org/abs/2404.12272" target="_blank" rel="noreferrer">Shankar et al.</a>); high percent agreement can hide large gaps between an LLM judge and humans, so report κ (<a href="https://arxiv.org/abs/2406.12624" target="_blank" rel="noreferrer">Thakur et al.</a>); and an always-pass judge scores 95% agreement when 5% of outputs fail (<a href="https://hamel.dev/blog/posts/llm-judge/" target="_blank" rel="noreferrer">Husain</a>). Treat eval questions as a sample with standard errors and paired comparisons (<a href="https://arxiv.org/abs/2411.00640" target="_blank" rel="noreferrer">Miller</a>); measure reliability with pass^k, which fell below 25% at k = 8 in τ-bench&#39;s retail domain (<a href="https://arxiv.org/abs/2406.12045" target="_blank" rel="noreferrer">Yao et al.</a>). The structured-output debate is a good replication target: format restrictions were reported to hurt reasoning (<a href="https://aclanthology.org/2024.emnlp-industry.91/" target="_blank" rel="noreferrer">Tam et al.</a>), but with matched prompts they did not (<a href="https://blog.dottxt.ai/say-what-you-mean.html" target="_blank" rel="noreferrer">.txt</a>).</p><h3 id="skills-and-professional-norms" tabindex="-1">Skills and professional norms <a class="header-anchor" href="#skills-and-professional-norms" aria-label="Permalink to &quot;Skills and professional norms&quot;">​</a></h3><p>Higher confidence in AI predicted less critical thinking among 319 knowledge workers (<a href="https://advait.org/files/lee_2025_ai_critical_thinking_survey.pdf" target="_blank" rel="noreferrer">Lee et al.</a>); students with an editing agent finished faster but understood less, and still preferred agents (<a href="https://arxiv.org/abs/2607.26375" target="_blank" rel="noreferrer">Balepur et al.</a>). Employment of developers aged 22–25 fell nearly 20% from its late-2022 peak, though the decline is significant only after 2024 under stricter controls and partly non-AI (<a href="https://digitaleconomy.stanford.edu/news/canaries-interest-rates-and-timinga-more-on-recent-drivers-of-employment-changes-for-young-workers" target="_blank" rel="noreferrer">Brynjolfsson et al.</a>). Projects converge on &quot;disclose, understand, take responsibility&quot; but disagree on recording: QEMU&#39;s pending proposal uses an <code>AI-used-for:</code> trailer (<a href="https://patchew.org/QEMU/20260529094619.1034458-1-pbonzini@redhat.com/" target="_blank" rel="noreferrer">patch</a>), and the Linux kernel dropped its tag requirement in October 2026 while keeping &quot;AI agents MUST NOT add Signed-off-by tags&quot; (<a href="https://github.com/torvalds/linux/blob/master/Documentation/process/coding-assistants.rst" target="_blank" rel="noreferrer">kernel</a>; <a href="https://hackaday.com/2026/10/15/linux-kernel-drops-ai-tag-requirement-uses-meta-ai-for-code-reviews/" target="_blank" rel="noreferrer">Hackaday</a>). Detection can&#39;t replace attribution: commit detectors reach precision 0.332 at realistic prevalence (<a href="https://arxiv.org/abs/2610.36229" target="_blank" rel="noreferrer">Horikawa et al.</a>). On licensing, even the best LLMs produced 0.88–2.01% of outputs strikingly similar to existing open-source code, with poor licence information for copyleft (<a href="https://arxiv.org/abs/2408.02487" target="_blank" rel="noreferrer">Xu et al.</a>), and the human-authorship requirement for copyright stands (<a href="https://www.scotusblog.com/cases/case-files/thaler-v-perlmutter" target="_blank" rel="noreferrer">Thaler v. Perlmutter</a>).</p><h3 id="where-sources-disagree" tabindex="-1">Where sources disagree <a class="header-anchor" href="#where-sources-disagree" aria-label="Permalink to &quot;Where sources disagree&quot;">​</a></h3><p>The cycle-time effect of AI reviewers (Beko +42% against Atlassian −30.8%); He et al.&#39;s complexity figure (+40.7% in a table, 25.1% in the text); SWE-Bench Pro&#39;s scores (tables, conclusion and vendor claims all differ: <a href="https://arxiv.org/abs/2509.16941" target="_blank" rel="noreferrer">Deng et al.</a>); and the kernel&#39;s <code>Assisted-by</code> tag, described as current in earlier notes and gone as of November 2026 (<a href="./notes/evidence-senior.html#index">evidence notes</a>).</p><h2 id="5-the-0-tool-landscape" tabindex="-1">5. The $0 tool landscape <a class="header-anchor" href="#5-the-0-tool-landscape" aria-label="Permalink to &quot;5. The $0 tool landscape&quot;">​</a></h2><p>Full tables, labels and sources: <a href="./notes/tools-senior.html">Course B (&quot;Engineering Software with AI&quot;): the $0 tool landscape, checked 2 November 2026</a>; the student handout: <a href="./../TOOLS.html">Tool Handout</a>.</p><ul><li><strong>Capacity, not tools, is scarce.</strong> VS Code, Copilot CLI, Gemini CLI, OpenCode, Cline, Goose, the MCP SDKs, CodeQL, Semgrep, Stryker and promptfoo are all free. Copilot Student&#39;s allowance is unpublished; third parties report about $2 a month, students report it gone &quot;after about 10 to 20 Agent Mode requests&quot;, and one default-effort Copilot code review averages about $1.50 (<a href="./notes/tools-senior.html#1-coding-agents-at-0-for-verified-university-students">tool notes, §1</a>).</li><li><strong>The free pools are separate.</strong> The Gemini API&#39;s free tier (limits unpublished; Gemini CLI allows 250 requests a day) is the largest, but it trains on prompts with human review. Groq&#39;s 8K-tokens-per-minute limit is smaller than one IDE-agent turn but fine for a lean student-built agent; OpenRouter&#39;s free models allow 50 requests a day; Jules allows 15 background tasks a day; CodeRabbit is free on public repositories; Zed Student gives a year of hosted tokens (<a href="./notes/tools-senior.html#2-open-source-agents-that-run-on-free-models">tool notes, §1–2</a>).</li><li><strong>Local models work for the student-built agent, MCP testing, evals and small fixes, not for navigating large codebases.</strong> A 24–32 GB GPU runs mid-size coding models; 16 GB laptops run small ones. Ollama&#39;s default context is 4K under 24 GiB of VRAM, and without a 64K setting &quot;tool calls silently fail because the system prompt gets truncated&quot; (<a href="./notes/tools-senior.html#3-local-models-for-agentic-coding">tool notes, §3</a>; <a href="https://docs.ollama.com/context-length" target="_blank" rel="noreferrer">Ollama</a>). One GPU serving a class is one shared queue.</li><li><strong>Infrastructure is free on public repositories:</strong> standard Actions runners, CodeQL with Autofix, secret scanning and push protection (<a href="./notes/tools-senior.html#4-free-infrastructure-for-the-courses-techniques">tool notes, §4</a>). Agentic Workflows default to a per-run cap five times a student&#39;s monthly Copilot allowance, so caps must be lowered.</li><li><strong>2026 broke 2025&#39;s labs:</strong> Gemini CLI&#39;s free login ended, the Gemini Code Assist review app shut down, GitHub Models was retired, Amazon Q&#39;s free tier closed, Kiro&#39;s student offer excludes UIdaho, Aider went dormant, and Copilot&#39;s new cloud experience is for &quot;paid Copilot plans only&quot;, with Student&#39;s status unverified (<a href="./notes/tools-senior.html#6-risks-for-a-0-design-what-broke-in-202526-and-fallbacks">tool notes, §6</a>).</li><li><strong>MCP is moving:</strong> the current specification has a stateless core with no <code>initialize</code> handshake, and a <code>tools/call</code> redesign is on the roadmap, so courses shouldn&#39;t grade the exact result shape (<a href="./notes/tools-senior.html#5-mcp-in-late-2026">tool notes, §5</a>).</li></ul><p><strong>Ranked risks:</strong> Copilot Student&#39;s tiny pool; the Gemini free tier&#39;s unpublished, changeable limits and data use; Copilot&#39;s paid-only cloud features; maintainers throttling AI-assisted PRs; weak local models; and offer deadlines falling inside or before a term (<a href="./notes/tools-senior.html#recommended-0-stack-for-course-b">tool notes</a>).</p><h2 id="6-design-implications" tabindex="-1">6. Design implications <a class="header-anchor" href="#6-design-implications" aria-label="Permalink to &quot;6. Design implications&quot;">​</a></h2><ol><li><strong>Frame everything with Specify · Delegate · Verify</strong> (UT Austin), carry the sibling course&#39;s Safe Loop as the inner loop, and tag every claim observed or inferred (Stanford CS146S).</li><li><strong>Build an agent in week 1, then move to a real harness in week 2.</strong> Michigan&#39;s pivot argues against a multi-week build; a one-week build makes the real harness legible.</li><li><strong>Teach security in week 4,</strong> before teams give agents broad access in the team project, as UT Austin does in week 3. Use an injection lab against the student&#39;s own agent, with a canary and localhost attacker, because injection rates of up to 84% make the case on their own.</li><li><strong>Measure test adequacy with mutation score,</strong> with the ISSTA 2026 caveat, and put property-based testing first, because LLM oracles encode actual behavior.</li><li><strong>Run the team project in three tiers</strong> and grade process, not merges.</li><li><strong>Keep AI-free checks short and frequent</strong> (7-minute due-date quizzes) and add individual oral exams and a final defense, because commit history and demos alone don&#39;t show understanding.</li><li><strong>Give graduate students presentations, a critique and a $0 replication study,</strong> worth about 20%, with a no-human-subjects rule.</li><li><strong>Spread tool load across free pools and a lab machine,</strong> with provider-swappable kits and a mid-term tool re-check.</li><li><strong>Teach evals as experiments</strong> (κ, pass^k, error bars, recorded responses) and benchmarks as claims to interrogate.</li><li><strong>Respect UIdaho&#39;s calendar rules:</strong> no quizzes or exams in week 15 (H-1-a), the final defense in the final exam slot (H-1-b).</li></ol><p>Each is traced to its evidence and its place in the course in <a href="./design-rationale.html">Why the Course Looks Like This</a>.</p><h2 id="7-gaps" tabindex="-1">7. Gaps <a class="header-anchor" href="#7-gaps" aria-label="Permalink to &quot;7. Gaps&quot;">​</a></h2><ul><li><strong>No outcome data</strong> for mutation-testing, prompt-injection or parallel-agent labs in any course, or for 2026 merge rates of student PRs (<a href="./notes/courses-upper-division.html#gaps">courses notes</a>).</li><li><strong>Unpublished:</strong> CS146S&#39;s open-source rubric; Michigan&#39;s later weeks; Brown&#39;s Agentic Studio syllabus.</li><li><strong>Unverified tool facts:</strong> Copilot Student&#39;s allowance size and &quot;paid plan&quot; status; Groq&#39;s free-tab figures; CodeRabbit&#39;s data terms; UIdaho&#39;s Microsoft Copilot protections (<a href="./notes/tools-senior.html#gaps-could-not-verify-on-2026-11-02">tool notes, Gaps</a>).</li><li><strong>Secondary-only:</strong> the SWE-bench Verified flaw rate (coverage of a 403 page), GitHub&#39;s PR-cap details and the AIDev acceptance percentages (search summaries).</li><li><strong>The evidence on parallel agents and subagents</strong> is practitioner consensus, not measurement.</li></ul>',58)])])}const g=t(s,[["render",n]]);export{p as __pageData,g as default};
